import type * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

// 像素约定：竖线是 GridContainer 的 border-x（位于内容区外 1px），
// 上方横线是上一行的底线（同样在外 1px），本行底线由 screen-line-bottom 画在内侧最后 1px。
// 十字为 11px 方框，线在第 5 px，所以用整数偏移让中心正好压在线条像素上，不用 translate(-50%)。
const gridCrosshairVariants = cva(
  "pointer-events-none absolute z-10 size-[11px] before:absolute before:inset-y-0 before:left-[5px] before:w-px before:bg-foreground/45 after:absolute after:inset-x-0 after:top-[5px] after:h-px after:bg-foreground/45",
  {
    variants: {
      /**
       * 十字所在的角：top-left、top-right、bottom-left、bottom-right
       * @default "top-left"
       */
      position: {
        "top-left": "-top-[6px] -left-[6px]",
        "top-right": "-top-[6px] -right-[6px]",
        "bottom-left": "-bottom-[5px] -left-[6px]",
        "bottom-right": "-right-[6px] -bottom-[5px]",
      },
      /**
       * 十字的定位基准。line：底线由 screen-line-bottom 画在元素内侧（GridSection / GridSeparator）；border：元素自身有四边 border
       * @default "line"
       */
      anchor: { line: "", border: "" },
    },
    compoundVariants: [
      { anchor: "border", position: "bottom-left", className: "-bottom-[6px]" },
      {
        anchor: "border",
        position: "bottom-right",
        className: "-bottom-[6px]",
      },
    ],
    defaultVariants: { position: "top-left", anchor: "line" },
  },
)

// 纹理层：高 31px（不覆盖底线），左端在左竖线外 4096px，平铺原点因此正好落在竖线上
const gridSeparatorVariants = cva(
  "absolute top-0 bottom-px -left-[4097px] -right-[4096px]",
  {
    variants: {
      pattern: {
        ruler: "pattern-ruler",
        hatch: "pattern-hatch",
        dots: "pattern-dots",
        grid: "pattern-grid",
        plus: "pattern-plus",
        wave: "pattern-wave",
        none: "",
      },
    },
    defaultVariants: { pattern: "dots" },
  },
)

type GridSeparatorPattern = NonNullable<
  VariantProps<typeof gridSeparatorVariants>["pattern"]
>

/**
 * 交点十字：绘制在容器竖线与横线交点处的小「+」，纯装饰。
 * 放在带 `position: relative` 的行（GridSection、GridSeparator）内，由 position 指定四个角之一。
 */
function GridCrosshair({
  className,
  position,
  anchor,
  ...props
}: React.ComponentProps<"span"> & VariantProps<typeof gridCrosshairVariants>) {
  return (
    <span
      aria-hidden
      data-slot="grid-crosshair"
      data-position={position ?? "top-left"}
      className={cn(gridCrosshairVariants({ position, anchor }), className)}
      {...props}
    />
  )
}

/**
 * 页面主容器：固定宽度 + 左右竖线。
 * 宽度可通过 CSS 变量 --grid-width 覆盖（默认 48rem）。
 * 外宽多 1px，使左右两条竖线的间距正好等于 --grid-width（纹路周期都能整除它）。
 * 视口窄于容器时，两侧各留出 gutter：竖线向内缩，全宽横线仍延伸到屏幕边缘，形成「线框中的内容」。
 * gutter 是两侧之和，用 CSS 变量 --grid-gutter 覆盖（默认窄屏 2rem、sm 起 3rem；设为 0px 则竖线贴边）。
 */
function GridContainer({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="grid-container"
      className={cn(
        "mx-auto w-[calc(100%-var(--grid-gutter,2rem))] max-w-[calc(var(--grid-width,48rem)+1px)] border-x border-edge sm:w-[calc(100%-var(--grid-gutter,3rem))]",
        className,
      )}
      {...props}
    />
  )
}

/**
 * 一行内容：底部一条横跨整个屏幕的分隔线。
 * 放在 GridContainer 内使用。
 */
function GridSection({
  className,
  topLine = false,
  crosshair = false,
  children,
  ...props
}: React.ComponentProps<"section"> & {
  /**
   * 在行的顶部补一条全屏横线（默认只画底线）
   * @default false
   */
  topLine?: boolean
  /**
   * 在底线与左右竖线的两个交点处绘制「+」
   * @default false
   */
  crosshair?: boolean
}) {
  return (
    <section
      data-slot="grid-section"
      data-top-line={topLine}
      className={cn(
        "screen-line-bottom",
        topLine && "screen-line-top",
        className,
      )}
      {...props}
    >
      {children}
      {crosshair ? (
        <>
          <GridCrosshair position="bottom-left" />
          <GridCrosshair position="bottom-right" />
        </>
      ) : null}
    </section>
  )
}

/**
 * 分隔带：全屏宽度的纹理 + 底部横线，用于主题切换处。
 * 默认是点阵纹路；需要时可用 crosshair 在交点绘制「+」。
 */
function GridSeparator({
  className,
  pattern,
  label,
  crosshair,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof gridSeparatorVariants> & {
    /**
     * 纹路：dots、ruler、hatch、grid、plus、wave，none 为只留线条
     * @default "dots"
     */
    pattern?: GridSeparatorPattern | null
    /** 左侧的等宽小字编号（如 `02 / PROJECTS`），像标签一样贴在纹路上；可与任意纹路组合 */
    label?: React.ReactNode
    /**
     * 是否在四个交点绘制十字
     * @default false
     */
    crosshair?: boolean
  }) {
  const resolved = pattern ?? "dots"
  const showCrosshair = crosshair ?? false
  return (
    <div
      aria-hidden
      data-slot="grid-separator"
      data-pattern={resolved}
      className={cn("screen-line-bottom h-8 w-full", className)}
      {...props}
    >
      {resolved === "ruler" ? (
        // 刻度尺带一层极淡的底色，让分隔带读作一条「带子」
        <div className="absolute top-0 -right-[4096px] bottom-px -left-[4097px] bg-foreground/[0.025]" />
      ) : null}
      <div
        data-slot="grid-separator-pattern"
        className={gridSeparatorVariants({ pattern: resolved })}
      />
      {label ? (
        <div
          data-slot="grid-separator-label"
          className="absolute inset-y-0 left-4 flex items-center sm:left-6"
        >
          <span className="bg-background px-1.5 font-mono text-[11px] leading-4 tracking-[0.08em] whitespace-nowrap text-muted-foreground">
            {label}
          </span>
        </div>
      ) : null}
      {showCrosshair ? (
        <>
          <GridCrosshair position="top-left" />
          <GridCrosshair position="top-right" />
          <GridCrosshair position="bottom-left" />
          <GridCrosshair position="bottom-right" />
        </>
      ) : null}
    </div>
  )
}

/**
 * 分栏：栏与栏之间用虚线分隔，窄屏自动堆叠。
 */
function GridColumns({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="grid-columns"
      className={cn(
        "grid grid-cols-1 divide-y divide-dashed divide-edge sm:grid-cols-2 sm:divide-x sm:divide-y-0",
        className,
      )}
      {...props}
    />
  )
}

export {
  GridColumns,
  GridContainer,
  GridCrosshair,
  GridSection,
  GridSeparator,
  gridCrosshairVariants,
  gridSeparatorVariants,
}
export type { GridSeparatorPattern }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { useNow } from "@/registry/hooks/use-now"

import { AnalogClock, type AnalogClockProps } from "./analog-clock"
import { DEFAULT_LABELS, type LocalTimeLabels } from "./config"
import { DayNightMark, TimeDigits } from "./time-parts"
import {
  WorldClock,
  WorldClockItem,
  type WorldClockItemProps,
  type WorldClockProps,
  type WorldClockVariant,
  type WorldClockZone,
} from "./world-clock"
import {
  clockParts,
  describeDifference,
  hourDifference,
  isDaytime,
  offsetMinutes,
  utcLabel,
  zoneHour,
} from "./zone"

type LocalTimeProps = Omit<React.ComponentProps<"span">, "children"> & {
  /** IANA 时区名，例如 `Asia/Shanghai`，不支持 `+08:00` 这类固定偏移 */
  timeZone: string
  /**
   * BCP 47 区域标识，决定时间与数字的格式
   * @default "zh-CN"
   */
  locale?: string
  /**
   * 12 小时制（带上午/下午），默认 24 小时制
   * @default false
   */
  hour12?: boolean
  /**
   * 显示秒；关闭后每分钟才刷新一次
   * @default true
   */
  showSeconds?: boolean
  /**
   * 在 `//` 后显示与访客时区的时差
   * @default true
   */
  showDifference?: boolean
  /**
   * 在时间后显示 UTC 偏移，例如 `UTC+8`
   * @default false
   */
  showZone?: boolean
  /**
   * 在时间前显示昼夜图标（6:00–17:59 为白天）
   * @default false
   */
  showDayNight?: boolean
  /**
   * 数字变化时播放轻微的下落淡入；系统开启“减少动态效果”时自动关闭
   * @default false
   */
  animated?: boolean
  /** 覆盖部分可见文案 */
  labels?: Partial<LocalTimeLabels>
  /**
   * 挂载前的占位时间；默认随 `showSeconds` 为 `--:--:--` 或 `--:--`
   */
  placeholder?: string
  /** @deprecated 等价于 `labels.pending` */
  placeholderLabel?: string
  /** @deprecated 等价于 `labels.same` */
  sameTimeLabel?: string
  /** @deprecated 等价于 `labels.ahead` */
  aheadLabel?: string
  /** @deprecated 等价于 `labels.behind` */
  behindLabel?: string
  /** @deprecated 等价于 `labels.hourUnit` */
  hourUnit?: string
}

/** 以指定 IANA 时区显示时间，并可附带 UTC 偏移、昼夜图标与同访客的时差。 */
function LocalTime({
  timeZone,
  className,
  locale = "zh-CN",
  hour12 = false,
  showSeconds = true,
  showDifference = true,
  showZone = false,
  showDayNight = false,
  animated = false,
  labels,
  placeholder,
  placeholderLabel,
  sameTimeLabel,
  aheadLabel,
  behindLabel,
  hourUnit,
  ...props
}: LocalTimeProps) {
  // 不显示秒时按分钟对齐，减少无谓的重新渲染
  const now = useNow(showSeconds ? 1000 : 60_000)
  const text = {
    ...DEFAULT_LABELS,
    ...labels,
    ...(placeholderLabel !== undefined && { pending: placeholderLabel }),
    ...(sameTimeLabel !== undefined && { same: sameTimeLabel }),
    ...(aheadLabel !== undefined && { ahead: aheadLabel }),
    ...(behindLabel !== undefined && { behind: behindLabel }),
    ...(hourUnit !== undefined && { hourUnit }),
  }

  if (now === null)
    return (
      <span
        data-slot="local-time"
        data-state="pending"
        className={cn("tabular-nums", className)}
        {...props}
      >
        {showDayNight ? (
          <span aria-hidden="true" className="mr-1.5 inline-block size-[1em]" />
        ) : null}
        {placeholder ?? (showSeconds ? "--:--:--" : "--:--")}
        {showDifference ? (
          <>
            {" "}
            <span
              data-slot="local-time-note"
              className="text-muted-foreground"
            >{`// ${text.pending}`}</span>
          </>
        ) : null}
      </span>
    )

  const date = new Date(now)
  const daylight = isDaytime(zoneHour(timeZone, date))
  return (
    <span
      data-slot="local-time"
      data-state="ready"
      data-daylight={showDayNight ? (daylight ? "day" : "night") : undefined}
      className={cn("tabular-nums", className)}
      {...props}
    >
      {showDayNight ? (
        <DayNightMark
          daylight={daylight}
          label={daylight ? text.day : text.night}
          className="mr-1.5"
        />
      ) : null}
      <time data-slot="local-time-time" dateTime={date.toISOString()}>
        <TimeDigits
          parts={clockParts(date, { locale, timeZone, hour12, showSeconds })}
          animated={animated}
        />
      </time>
      {showZone ? (
        <>
          {" "}
          <span data-slot="local-time-zone" className="text-muted-foreground">
            {utcLabel(offsetMinutes(timeZone, date))}
          </span>
        </>
      ) : null}
      {showDifference ? (
        <>
          {" "}
          <span
            data-slot="local-time-note"
            className="text-muted-foreground"
          >{`// ${describeDifference(hourDifference(timeZone, date), locale, text)}`}</span>
        </>
      ) : null}
    </span>
  )
}

export { AnalogClock, LocalTime, WorldClock, WorldClockItem }
export type {
  AnalogClockProps,
  LocalTimeLabels,
  LocalTimeProps,
  WorldClockItemProps,
  WorldClockProps,
  WorldClockVariant,
  WorldClockZone,
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { useNow } from "@/registry/hooks/use-now"

import { AnalogClock } from "./analog-clock"
import { DEFAULT_LABELS, type LocalTimeLabels } from "./config"
import { DayNightMark, TimeDigits } from "./time-parts"
import {
  clockParts,
  dayOffset,
  describeDifference,
  hourDifference,
  isDaytime,
  offsetMinutes,
  utcLabel,
  zoneHour,
} from "./zone"

/** `list` 一行一个城市；`cards` 每个城市是一张带模拟表盘的卡片，两列排布。 */
type WorldClockVariant = "list" | "cards"

type WorldClockZone = {
  /** IANA 时区名 */
  timeZone: string
  /** 城市名 */
  label: React.ReactNode
  /** 高亮这一项（例如“我所在的城市”） */
  highlighted?: boolean
}

type WorldClockSettings = {
  locale: string
  hour12: boolean
  showSeconds: boolean
  showZone: boolean
  animated: boolean
  variant: WorldClockVariant
  labels: LocalTimeLabels
}

const WorldClockContext = React.createContext<WorldClockSettings>({
  locale: "zh-CN",
  hour12: false,
  showSeconds: true,
  showZone: true,
  animated: true,
  variant: "list",
  labels: DEFAULT_LABELS,
})

type WorldClockProps = Omit<React.ComponentProps<"div">, "title"> & {
  /** 用数据描述城市；与 `children` 二选一，同时传入时两者都会渲染 */
  zones?: readonly WorldClockZone[]
  /**
   * 排布方式
   * @default "list"
   */
  variant?: WorldClockVariant
  /**
   * 标题栏内容；传 `null` 隐藏整条标题栏
   * @default "WORLD CLOCK"
   */
  title?: React.ReactNode
  /**
   * BCP 47 区域标识，决定时间与数字的格式
   * @default "zh-CN"
   */
  locale?: string
  /**
   * 12 小时制（带上午/下午），默认 24 小时制
   * @default false
   */
  hour12?: boolean
  /**
   * 显示秒
   * @default true
   */
  showSeconds?: boolean
  /**
   * 在城市名下显示 UTC 偏移
   * @default true
   */
  showZone?: boolean
  /**
   * 数字变化时播放轻微的下落淡入；系统开启“减少动态效果”时自动关闭
   * @default true
   */
  animated?: boolean
  /** 覆盖部分可见文案 */
  labels?: Partial<LocalTimeLabels>
}

/** 世界时钟：多个时区同时显示，右侧标出与访客的时差、昼夜和日期差。 */
function WorldClock({
  zones,
  variant = "list",
  title,
  locale = "zh-CN",
  hour12 = false,
  showSeconds = true,
  showZone = true,
  animated = true,
  labels,
  className,
  children,
  ...props
}: WorldClockProps) {
  const text = React.useMemo(() => ({ ...DEFAULT_LABELS, ...labels }), [labels])
  const settings = React.useMemo(
    () => ({
      locale,
      hour12,
      showSeconds,
      showZone,
      animated,
      variant,
      labels: text,
    }),
    [locale, hour12, showSeconds, showZone, animated, variant, text],
  )
  const heading = title === undefined ? text.worldClock : title
  return (
    <WorldClockContext.Provider value={settings}>
      <div
        data-slot="world-clock"
        data-variant={variant}
        role="group"
        aria-label={typeof heading === "string" ? heading : text.worldClock}
        className={cn(
          "overflow-hidden rounded-lg border border-edge bg-background",
          className,
        )}
        {...props}
      >
        {heading === null ? null : (
          <div
            data-slot="world-clock-header"
            className="flex items-center justify-between gap-3 border-b border-edge px-3 py-2 font-mono text-[10px] tracking-[0.08em] text-muted-foreground"
          >
            <span className="min-w-0 truncate">{heading}</span>
            <span className="flex shrink-0 items-center gap-1.5">
              <span
                aria-hidden="true"
                className="size-1.5 rounded-full bg-primary motion-safe:animate-pulse"
              />
              {text.live}
            </span>
          </div>
        )}
        <ul
          data-slot="world-clock-list"
          className={cn(
            variant === "list"
              ? "divide-y divide-edge"
              : // 单元格自带右、下边线，用负外边距把最外一圈挤出外框的裁剪区，避免与外框叠成双线
                "-mr-px -mb-px grid grid-cols-2 *:border-r *:border-b *:border-edge [&>li:last-child:nth-child(odd)]:col-span-2",
          )}
        >
          {zones?.map((zone) => (
            <WorldClockItem
              key={zone.timeZone}
              timeZone={zone.timeZone}
              label={zone.label}
              highlighted={zone.highlighted}
            />
          ))}
          {children}
        </ul>
      </div>
    </WorldClockContext.Provider>
  )
}

type WorldClockItemProps = Omit<React.ComponentProps<"li">, "children"> & {
  /** IANA 时区名 */
  timeZone: string
  /** 城市名 */
  label: React.ReactNode
  /**
   * 高亮这一项
   * @default false
   */
  highlighted?: boolean
}

/** 世界时钟中的一个城市；必须放在 `WorldClock` 里。 */
function WorldClockItem({
  timeZone,
  label,
  highlighted = false,
  className,
  ...props
}: WorldClockItemProps) {
  const { locale, hour12, showSeconds, showZone, animated, variant, labels } =
    React.useContext(WorldClockContext)
  const now = useNow(showSeconds ? 1000 : 60_000)
  const date = now === null ? null : new Date(now)
  const daylight = date ? isDaytime(zoneHour(timeZone, date)) : true
  const days = date ? dayOffset(timeZone, date) : 0
  const meta = date
    ? [
        days === 0 ? null : days > 0 ? labels.tomorrow : labels.yesterday,
        describeDifference(hourDifference(timeZone, date), locale, labels),
      ]
        .filter(Boolean)
        .join(" · ")
    : ""
  const zone = [
    timeZone.replaceAll("_", " "),
    date && showZone ? utcLabel(offsetMinutes(timeZone, date)) : null,
  ]
    .filter(Boolean)
    .join(" · ")
  const time = date ? (
    <time data-slot="world-clock-time" dateTime={date.toISOString()}>
      <TimeDigits
        parts={clockParts(date, { locale, timeZone, hour12, showSeconds })}
        animated={animated}
      />
    </time>
  ) : (
    <span data-slot="world-clock-time">
      {showSeconds ? "--:--:--" : "--:--"}
    </span>
  )
  const mark = date ? (
    <DayNightMark
      daylight={daylight}
      label={daylight ? labels.day : labels.night}
      className="size-3.5"
    />
  ) : null

  return (
    <li
      data-slot="world-clock-item"
      data-state={date ? "ready" : "pending"}
      data-highlighted={highlighted ? "" : undefined}
      data-daylight={date ? (daylight ? "day" : "night") : undefined}
      className={cn(
        "relative min-w-0 data-[highlighted]:bg-primary/5 data-[highlighted]:before:absolute data-[highlighted]:before:inset-y-0 data-[highlighted]:before:left-0 data-[highlighted]:before:w-0.5 data-[highlighted]:before:bg-primary",
        variant === "list"
          ? "flex items-center justify-between gap-3 px-3 py-2"
          : "flex flex-col items-center gap-2 px-3 py-4 text-center",
        className,
      )}
      {...props}
    >
      {variant === "cards" ? (
        <AnalogClock
          timeZone={timeZone}
          locale={locale}
          label={typeof label === "string" ? label : labels.clock}
          showSeconds={showSeconds}
          className="size-20"
        />
      ) : null}
      <div
        className={cn("min-w-0", variant === "list" ? "flex-1" : "max-w-full")}
      >
        <p className="truncate text-sm leading-5 font-medium">{label}</p>
        <p className="truncate font-mono text-[10px] leading-4 text-muted-foreground">
          {zone}
        </p>
      </div>
      <div
        className={cn(
          "shrink-0 font-mono",
          variant === "list" ? "text-right" : "text-center",
        )}
      >
        <p
          className={cn(
            "flex items-center gap-1.5 text-sm leading-5 tabular-nums",
            variant === "list" ? "justify-end" : "justify-center",
          )}
        >
          {mark}
          {time}
        </p>
        <p className="min-h-4 text-[10px] leading-4 whitespace-nowrap text-muted-foreground">
          {meta}
        </p>
      </div>
    </li>
  )
}

export { WorldClock, WorldClockItem }
export type {
  WorldClockItemProps,
  WorldClockProps,
  WorldClockVariant,
  WorldClockZone,
}

"use client"

import * as React from "react"
import { useAnimationFrame, useInView, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { useNow } from "@/registry/hooks/use-now"

import { DEFAULT_LABELS } from "./config"
import { isDaytime, offsetMinutes, zoneHour } from "./zone"

type AnalogClockProps = Omit<React.ComponentProps<"svg">, "children"> & {
  /** IANA 时区名，例如 `Asia/Shanghai` */
  timeZone: string
  /**
   * BCP 47 区域标识，决定读屏标签里的时间格式
   * @default "zh-CN"
   */
  locale?: string
  /**
   * 显示秒针
   * @default true
   */
  showSeconds?: boolean
  /**
   * 指针每帧平滑转动；关闭后按秒跳格。系统开启“减少动态效果”时自动按秒跳格
   * @default true
   */
  smooth?: boolean
  /**
   * 读屏名称，后面会拼上当前时间
   * @default "当地时间"
   */
  label?: string
}

/** 时间折算成三根指针的角度（度）；`seconds` 带毫秒，用于平滑转动。 */
function handAngles(zonedSeconds: number) {
  const day = ((zonedSeconds % 86_400) + 86_400) % 86_400
  return {
    hour: (day % 43_200) / 120,
    minute: (day % 3600) / 10,
    second: (day % 60) * 6,
  }
}

/**
 * SVG 模拟表盘。表盘随昼夜轻微变色，秒针用主题强调色。
 * 平滑模式下指针由 `requestAnimationFrame` 直接写入 transform，不经过 React 渲染；
 * 离开视口时暂停。
 */
function AnalogClock({
  timeZone,
  locale = "zh-CN",
  showSeconds = true,
  smooth = true,
  label = DEFAULT_LABELS.clock,
  className,
  ...props
}: AnalogClockProps) {
  const reduced = useReducedMotion()
  const continuous = smooth && !reduced
  const now = useNow(continuous ? 60_000 : 1000)
  const ref = React.useRef<SVGSVGElement>(null)
  const inView = useInView(ref)
  const hands = React.useRef<
    Record<"hour" | "minute" | "second", SVGGElement | null>
  >({ hour: null, minute: null, second: null })
  const date = now === null ? null : new Date(now)
  const offset = date ? offsetMinutes(timeZone, date) : null
  // 动画帧里不能再算时区：偏移随渲染（至少每分钟）更新到 ref，帧回调只做加法
  const offsetRef = React.useRef<number | null>(null)
  React.useEffect(() => {
    offsetRef.current = offset
  }, [offset])

  useAnimationFrame(() => {
    if (!continuous || !inView || offsetRef.current === null) return
    const angles = handAngles(Date.now() / 1000 + offsetRef.current * 60)
    hands.current.hour?.setAttribute(
      "transform",
      `rotate(${angles.hour} 50 50)`,
    )
    hands.current.minute?.setAttribute(
      "transform",
      `rotate(${angles.minute} 50 50)`,
    )
    hands.current.second?.setAttribute(
      "transform",
      `rotate(${angles.second} 50 50)`,
    )
  })

  // 非平滑模式由 React 按秒写入角度；平滑模式只写初始值 0，之后交给动画帧
  const stepped =
    !continuous && date && offset !== null
      ? handAngles(Math.floor(date.getTime() / 1000) + offset * 60)
      : { hour: 0, minute: 0, second: 0 }
  const daylight = date ? isDaytime(zoneHour(timeZone, date)) : true
  const description = date
    ? `${label} ${new Intl.DateTimeFormat(locale, {
        timeZone,
        hour: "2-digit",
        minute: "2-digit",
        hourCycle: "h23",
      }).format(date)}`
    : label

  return (
    <svg
      ref={ref}
      data-slot="analog-clock"
      data-state={date ? "ready" : "pending"}
      data-daylight={daylight ? "day" : "night"}
      viewBox="0 0 100 100"
      role="img"
      aria-label={description}
      className={cn("size-28 text-foreground", className)}
      {...props}
    >
      <circle
        cx="50"
        cy="50"
        r="48.5"
        className={cn(
          "stroke-edge",
          daylight ? "fill-background" : "fill-foreground/5",
        )}
        strokeWidth="1"
      />
      {Array.from({ length: 12 }, (_, index) => (
        <line
          key={index}
          x1="50"
          x2="50"
          y1={index % 3 === 0 ? 6 : 8}
          y2={index % 3 === 0 ? 13 : 11.5}
          transform={`rotate(${index * 30} 50 50)`}
          className={
            index % 3 === 0 ? "stroke-foreground/70" : "stroke-foreground/30"
          }
          strokeWidth={index % 3 === 0 ? 1.6 : 1}
          strokeLinecap="round"
        />
      ))}
      <g
        ref={(node) => void (hands.current.hour = node)}
        transform={`rotate(${stepped.hour} 50 50)`}
      >
        <line
          x1="50"
          y1="54"
          x2="50"
          y2="29"
          className="stroke-foreground"
          strokeWidth="3"
          strokeLinecap="round"
        />
      </g>
      <g
        ref={(node) => void (hands.current.minute = node)}
        transform={`rotate(${stepped.minute} 50 50)`}
      >
        <line
          x1="50"
          y1="56"
          x2="50"
          y2="17"
          className="stroke-foreground"
          strokeWidth="2"
          strokeLinecap="round"
        />
      </g>
      {showSeconds ? (
        <g
          ref={(node) => void (hands.current.second = node)}
          transform={`rotate(${stepped.second} 50 50)`}
        >
          <line
            x1="50"
            y1="60"
            x2="50"
            y2="13"
            className="stroke-primary"
            strokeWidth="1"
            strokeLinecap="round"
          />
        </g>
      ) : null}
      <circle cx="50" cy="50" r="2.4" className="fill-primary" />
      <circle cx="50" cy="50" r="0.9" className="fill-background" />
    </svg>
  )
}

export { AnalogClock }
export type { AnalogClockProps }

