  /** 标签行右侧的操作，例如「忘记密码？」 */
  labelAction?: ReactNode
  /** 输入框内右侧的元素，例如显示/隐藏密码按钮 */
  trailing?: ReactNode
  /** 输入框外右侧的元素，例如「获取验证码」按钮 */
  adjacent?: ReactNode
}) {
  const errorId = `${id}-error`
  return (
    <div data-slot="auth-01-text-field" className="flex flex-col gap-2">
