            aria-invalid={error ? true : undefined}
            aria-describedby={error ? errorId : undefined}
            className={cn("h-10 pl-9", trailing && "pr-10", className)}
            {...props}
          />
          {trailing}
        </div>
        {adjacent}
      </div>
