"use client"

import { AgentChatMarkdown } from "./chat-markdown"
import { useAgentContext } from "./agent-chat-context"
import { useEffect, useState } from "react"
import { isToolUIPart, getToolName, type UIMessage } from "ai"
import {
  Brain,
  Check,
  Copy,
  ExternalLink,
  LoaderCircle,
  RotateCcw,
  ThumbsDown,
  ThumbsUp,
  X,
} from "lucide-react"
import { Bubble, BubbleContent } from "@/components/ui/bubble"
import { Button } from "@/components/ui/button"
import { CodeBlock, CodeBlockContent } from "@/components/ui/code-block"
import { Message, MessageContent, MessageFooter } from "@/components/ui/message"
import {
  Trace,
  TraceCollapsible,
  TraceCollapsibleContent,
  TraceCollapsibleTrigger,
  TraceIcon,
  TraceLine,
  TraceTitle,
} from "@/components/ui/trace"

function messageText(message: UIMessage) {
  return message.parts
    .filter((part) => part.type === "text")
    .map((part) => part.text)
    .join("")
}

function AgentChatReasoning({
  text,
  running,
  interrupted,
}: {
  text: string
  running: boolean
  interrupted: boolean
}) {
  const { labels } = useAgentContext()
  const [seconds, setSeconds] = useState(0)
  useEffect(() => {
    if (!running) return
    const started = Date.now()
    const timer = setInterval(
      () => setSeconds((Date.now() - started) / 1000),
      100,
    )
    return () => clearInterval(timer)
  }, [running])
  return (
    <TraceCollapsible data-slot="agent-chat-reasoning">
      <TraceCollapsibleTrigger>
        <TraceLine status={running ? "running" : undefined}>
          <TraceIcon>
            {running ? (
              <LoaderCircle className="animate-spin motion-reduce:animate-none" />
            ) : (
              <Brain />
            )}
          </TraceIcon>
          <TraceTitle>
            {running
              ? labels.thinking
              : interrupted
                ? labels.thinkingStopped
                : seconds === 0
                  ? labels.reasoningSummary
                  : labels.thought.replace(
                      "{seconds}",
                      new Intl.NumberFormat(undefined, {
                        maximumFractionDigits: 1,
                      }).format(seconds),
                    )}
          </TraceTitle>
        </TraceLine>
      </TraceCollapsibleTrigger>
      <TraceCollapsibleContent>
        <p className="text-sm leading-7">{text || labels.preparing}</p>
      </TraceCollapsibleContent>
    </TraceCollapsible>
  )
}
function safeSource(url: string) {
  try {
    const parsed = new URL(url)
    return ["https:", "http:"].includes(parsed.protocol)
      ? parsed.href
      : undefined
  } catch {
    return undefined
  }
}

function AgentChatMessage({
  message,
  live,
  busy,
  regenerate,
}: {
  message: UIMessage
  live: boolean
  busy: boolean
  regenerate: () => void
}) {
  const { labels } = useAgentContext()
  const [feedback, setFeedback] = useState<"up" | "down" | null>(null)
  const [notice, setNotice] = useState("")
  const text = messageText(message)
  if (message.role === "user")
    return (
      <Message data-slot="agent-chat-message" data-role="user" align="end">
        <MessageContent>
          <Bubble align="end" variant="muted">
            <BubbleContent>{text}</BubbleContent>
          </Bubble>
        </MessageContent>
      </Message>
    )
  return (
    <Message
      data-slot="agent-chat-message"
      data-role="assistant"
      data-state={live ? "streaming" : "idle"}
    >
      <MessageContent className="gap-4">
        <Trace>
          {message.parts.map((part, index) => {
            if (part.type === "reasoning")
              return (
                <AgentChatReasoning
                  key={index}
                  text={part.text}
                  running={live && part.state === "streaming"}
                  interrupted={!live && part.state === "streaming"}
                />
              )
            if (isToolUIPart(part)) {
              const done = part.state === "output-available"
              const failed =
                part.state === "output-error" || part.state === "output-denied"
              const running = live && !done && !failed
              const label = `${running ? labels.running : done ? labels.completed : failed ? labels.failed : labels.stopped} · ${getToolName(part)}`
              return (
                <TraceCollapsible key={part.toolCallId}>
                  <TraceCollapsibleTrigger>
                    <TraceLine
                      status={
                        running ? "running" : failed ? "error" : undefined
                      }
                    >
                      <TraceIcon>
                        {running ? (
                          <LoaderCircle className="animate-spin motion-reduce:animate-none" />
                        ) : done ? (
                          <Check />
                        ) : (
                          <X />
                        )}
                      </TraceIcon>
                      <TraceTitle>{label}</TraceTitle>
                    </TraceLine>
                  </TraceCollapsibleTrigger>
                  <TraceCollapsibleContent>
                    <div className="flex flex-col gap-2">
                      <p className="text-xs">{labels.toolInput}</p>
                      <CodeBlock size="sm">
                        <CodeBlockContent wrap>
                          {JSON.stringify(part.input ?? {}, null, 2)}
                        </CodeBlockContent>
                      </CodeBlock>
                      <p className="text-xs">{labels.toolOutput}</p>
                      <CodeBlock
                        size="sm"
                        variant={failed ? "destructive" : "default"}
                      >
                        <CodeBlockContent wrap>
                          {part.state === "output-error"
                            ? part.errorText
                            : done
                              ? JSON.stringify(part.output, null, 2)
                              : part.state === "output-denied"
                                ? labels.denied
                                : running
                                  ? labels.waiting
                                  : labels.incomplete}
                        </CodeBlockContent>
                      </CodeBlock>
                    </div>
                  </TraceCollapsibleContent>
                </TraceCollapsible>
              )
            }
            if (part.type === "source-url") {
              const href = safeSource(part.url)
              return href ? (
                <a
                  key={part.sourceId}
                  href={href}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <TraceLine>
                    <TraceIcon>
                      <ExternalLink />
                    </TraceIcon>
                    <TraceTitle>
                      {part.title ?? new URL(href).hostname}
                      <span className="sr-only">{labels.newTab}</span>
                    </TraceTitle>
                  </TraceLine>
                </a>
              ) : null
            }
            return null
          })}
        </Trace>
        {text ? (
          <Bubble variant="ghost">
            <BubbleContent>
              <AgentChatMarkdown text={text} />
            </BubbleContent>
          </Bubble>
        ) : null}
        {!live ? (
          <MessageFooter className="flex-wrap gap-1">
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={labels.copy}
              disabled={!text}
              onClick={async () => {
                try {
                  await navigator.clipboard.writeText(text)
                  setNotice(labels.copied)
                } catch {
                  setNotice(labels.copyFailed)
                }
              }}
            >
              {notice === labels.copied ? <Check /> : <Copy />}
            </Button>
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={labels.useful}
              aria-pressed={feedback === "up"}
              onClick={() => {
                setFeedback(feedback === "up" ? null : "up")
                setNotice(labels.feedback)
              }}
            >
              <ThumbsUp />
            </Button>
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={labels.notUseful}
              aria-pressed={feedback === "down"}
              onClick={() => {
                setFeedback(feedback === "down" ? null : "down")
                setNotice(labels.feedback)
              }}
            >
              <ThumbsDown />
            </Button>
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={labels.regenerate}
              disabled={busy}
              onClick={regenerate}
            >
              <RotateCcw />
            </Button>
            <span role="status" className="text-xs">
              {notice}
            </span>
          </MessageFooter>
        ) : null}
      </MessageContent>
    </Message>
  )
}

export { AgentChatMessage, messageText }

import type { ReactNode } from "react"

// 仅解析段落、列表和行内代码；React 自动转义文本，不解释 HTML。
function inline(text: string): ReactNode {
  return text.split(/(`[^`]+`)/g).map((part, index) =>
    part.startsWith("`") && part.endsWith("`") ? (
      <code
        key={index}
        className="rounded bg-muted px-1 py-0.5 font-mono text-xs"
      >
        {part.slice(1, -1)}
      </code>
    ) : (
      part
    ),
  )
}
function AgentChatMarkdown({ text }: { text: string }) {
  return (
    <div
      data-slot="agent-chat-markdown"
      className="flex flex-col gap-3 leading-7"
    >
      {text.split(/\n\n+/).map((paragraph, index) => {
        const lines = paragraph.split("\n")
        if (lines.every((line) => /^[-*] /.test(line)))
          return (
            <ul key={index} className="flex list-disc flex-col gap-1 pl-5">
              {lines.map((line, i) => (
                <li key={i}>{inline(line.slice(2))}</li>
              ))}
            </ul>
          )
        if (lines.every((line) => /^\d+\. /.test(line)))
          return (
            <ol key={index} className="flex list-decimal flex-col gap-1 pl-5">
              {lines.map((line, i) => (
                <li key={i}>{inline(line.replace(/^\d+\. /, ""))}</li>
              ))}
            </ol>
          )
        return (
          <p key={index} className="whitespace-pre-wrap">
            {inline(paragraph)}
          </p>
        )
      })}
    </div>
  )
}

export { AgentChatMarkdown }

import type { ChatTransport, UIMessage, UIMessageChunk } from "ai"
import { scripts, fallback } from "./scripts"

function createMockTransport(): ChatTransport<UIMessage> {
  return {
    async sendMessages({ messages, abortSignal }) {
      const question =
        messages
          .findLast((message) => message.role === "user")
          ?.parts.filter((part) => part.type === "text")
          .map((part) => part.text)
          .join("") ?? ""
      const script =
        scripts.find((item) => item.match.test(question)) ?? fallback
      const queue: { chunk: UIMessageChunk; delay: number }[] = []
      const push = (chunk: UIMessageChunk, delay = 80) =>
        queue.push({ chunk, delay })
      push({ type: "start", messageId: crypto.randomUUID() }, 0)
      push({ type: "start-step" }, 0)
      push({ type: "reasoning-start", id: "reasoning" })
      for (const delta of script.reasoning.match(/.{1,8}/gu) ?? [])
        push({ type: "reasoning-delta", id: "reasoning", delta }, 130)
      push({ type: "reasoning-end", id: "reasoning" })
      for (const [index, tool] of script.tools.entries()) {
        const toolCallId = `tool-${index}`
        push({
          type: "tool-input-available",
          toolCallId,
          toolName: tool.name,
          input: tool.input,
          dynamic: true,
        })
        push(
          tool.error
            ? {
                type: "tool-output-error",
                toolCallId,
                errorText: tool.error,
                dynamic: true,
              }
            : {
                type: "tool-output-available",
                toolCallId,
                output: tool.output,
                dynamic: true,
              },
          800,
        )
      }
      push({ type: "source-url", sourceId: "reference", ...script.source })
      push({ type: "text-start", id: "answer" })
      for (const delta of script.answer.match(/.{1,6}|\n/gu) ?? [])
        push({ type: "text-delta", id: "answer", delta }, 35)
      push({ type: "text-end", id: "answer" })
      push({ type: "finish-step" }, 0)
      push({ type: "finish", finishReason: "stop" }, 0)
      let timer: ReturnType<typeof setTimeout> | undefined
      let finish: (() => void) | undefined
      let ended = false
      const cleanup = () => {
        ended = true
        clearTimeout(timer)
        finish?.()
        abortSignal?.removeEventListener("abort", abort)
      }
      let controller: ReadableStreamDefaultController<UIMessageChunk>
      const abort = () => {
        if (ended) return
        cleanup()
        controller.error(new DOMException("生成已停止", "AbortError"))
      }
      return new ReadableStream<UIMessageChunk>({
        start(value) {
          controller = value
          abortSignal?.addEventListener("abort", abort, { once: true })
          if (abortSignal?.aborted) abort()
        },
        async pull(value) {
          if (ended) return
          const next = queue.shift()
          if (!next) {
            cleanup()
            value.close()
            return
          }
          await new Promise<void>((resolve) => {
            finish = resolve
            timer = setTimeout(resolve, next.delay)
          })
          if (!ended) value.enqueue(next.chunk)
        },
        cancel() {
          cleanup()
        },
      })
    },
    async reconnectToStream() {
      return null
    },
  }
}

